const items = $input.all();

return items.filter(item => {
  const r = item.json;

  return (
    ['APPROVED', 'REVISION_REQUIRED'].includes(r.reviewStatus) &&
    String(r.reviewProcessedAt ?? '').trim() === ''
  );
});

const r = $json;

const humanDecisionValid =
  ['APPROVED', 'REVISION_REQUIRED'].includes(r.reviewStatus);

const assessmentValid =
  ['PASS', 'REVIEW_REQUIRED', 'FAIL'].includes(r.assessmentResult);

const progressionAllowed =
  r.reviewStatus === 'APPROVED' &&
  ['PASS', 'REVIEW_REQUIRED'].includes(r.assessmentResult);

const requiresRevision =
  r.reviewStatus === 'REVISION_REQUIRED' ||
  r.assessmentResult === 'FAIL';

const valid =
  /^MILO-[0-9]{3}$/.test(r.storyId ?? '') &&
  r.scriptId === `${r.storyId}-S01` &&
  r.reviewId === `${r.scriptId}-R01` &&
  Number(r.scriptVersion) >= 1 &&
  humanDecisionValid &&
  assessmentValid &&
  String(r.reviewProcessedAt ?? '').trim() === '' &&
  !(r.reviewStatus === 'APPROVED' && r.assessmentResult === 'FAIL');

return {
  json: {
    ...r,
    valid,
    progressionAllowed,
    requiresRevision
  }
};
